<?php $__env->startPush('scripts'); ?><script>document.addEventListener('DOMContentLoaded',()=>{const title=document.getElementById('job_title'),salary=document.getElementById('salary'),type=document.getElementById('type');if(title)title.addEventListener('change',()=>{if(!title.value)return;fetch(<?php echo json_encode(route('admin.hrms.jobadvertisements.salary-range', absolute:false), 512) ?>,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content,'Accept':'application/json'},body:JSON.stringify({position:title.value})}).then(r=>r.json()).then(d=>{salary.value=d.salary||'';if(d.employment_type)type.value=d.employment_type})});document.querySelectorAll('.status-select').forEach(select=>select.addEventListener('change',()=>{const old=select.dataset.old||select.value;fetch(<?php echo json_encode(url('/admin/hrms/jobadvertisements'), 15, 512) ?>.replace(/\/$/,'')+'/'+select.dataset.id+'/status',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content,'Accept':'application/json'},body:JSON.stringify({status:select.value})}).then(r=>r.json()).then(d=>{if(!d.success)select.value=old;else select.dataset.old=select.value}).catch(()=>select.value=old)}))})</script><?php $__env->stopPush(); ?>
